#!/usr/bin/env node
// Installed CLI for authorized queued startup.
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { startQueuedExecution } from "./execution-start-operation.mjs";

export { startQueuedExecution } from "./execution-start-operation.mjs";

function argumentsOf(argv) {
  if (argv[0] !== "start")
    throw new Error(
      "usage: execution-start.mjs start --integration PATH --workspace PATH --branch NAME --identity ID --publisher-id ID --mode trunk|story-branch --remote NAME --target BRANCH --push-authorized --workspace-authorized [--plan PATH] [--declared-owner ID --requester ID] [--starting-revision SHA --candidate-sha SHA]",
    );
  const result = {};
  for (let index = 1; index < argv.length; index += 1) {
    const flag = argv[index];
    if (flag === "--push-authorized" || flag === "--workspace-authorized") {
      result[
        flag === "--push-authorized" ? "pushAuthorized" : "workspaceAuthorized"
      ] = true;
      continue;
    }
    if (!flag.startsWith("--") || index + 1 >= argv.length)
      throw new Error(`invalid argument ${flag}`);
    const key = flag
      .slice(2)
      .replace(/-[a-z]/g, (match) => match[1].toUpperCase());
    result[key] = argv[++index];
  }
  return result;
}

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  try {
    const result = await startQueuedExecution(
      argumentsOf(process.argv.slice(2)),
    );
    process.stdout.write(`${JSON.stringify(result)}\n`);
    if (!result.ok) process.exitCode = 1;
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
  }
}

import { execFile } from "node:child_process";
import { existsSync, lstatSync, readFileSync, realpathSync } from "node:fs";
import { join, sep } from "node:path";
import { promisify } from "node:util";

const exec = promisify(execFile);

export function readProjectConvention(checkout) {
  const contributing = join(checkout, "CONTRIBUTING.md");
  if (!existsSync(contributing)) {
    return { missing: true, reason: "CONTRIBUTING.md is missing" };
  }
  const text = readFileSync(contributing, "utf8");
  const setup = text.match(/Locked setup:\s*`([^`]+)`/);
  const command = text.match(/Applicable command:\s*`([^`]+)`/);
  if (!setup || !command) {
    return {
      missing: true,
      reason: "setup or applicable command is ambiguous",
    };
  }
  return { setup: setup[1], command: command[1] };
}

async function runCommand(cwd, commandLine, env) {
  const [command, ...args] = commandLine.split(/\s+/).filter(Boolean);
  try {
    const result = await exec(command, args, {
      cwd,
      env,
      timeout: 60_000,
      maxBuffer: 2_000_000,
    });
    return {
      command: commandLine,
      cwd,
      code: 0,
      stdout: result.stdout,
      stderr: result.stderr,
    };
  } catch (error) {
    const code =
      typeof error.code === "number"
        ? error.code
        : error.code === "ERR_SOCKET_TIMEOUT"
          ? -1
          : 1;
    return {
      command: commandLine,
      cwd,
      code,
      stdout: error.stdout ?? "",
      stderr: error.stderr ?? String(error.message ?? error),
    };
  }
}

function failureReport(executionCheckout, command, failure) {
  return [
    `Failed to prepare execution checkout ${executionCheckout}`,
    `Command: ${command}`,
    failure,
  ].join("\n");
}

function sameCheckout(left, right) {
  try {
    return realpathSync(left) === realpathSync(right);
  } catch {
    return false;
  }
}

function hostEvidenceMatches(execution, hostPreparation, currentState) {
  if (!hostPreparation || currentState === undefined || currentState === null) {
    return false;
  }
  if (
    hostPreparation.dependencyState === undefined ||
    hostPreparation.dependencyState === null
  ) {
    return false;
  }
  if (hostPreparation.dependencyState !== currentState) return false;
  return sameCheckout(hostPreparation.checkout, execution);
}

// Ownership of mutable install in the selected checkout, not an availability
// test and not parent-directory or symlink reuse evidence.
function checkoutOwnsMutableInstall(checkout) {
  const installed = join(checkout, "node_modules");
  if (!existsSync(installed)) return false;
  try {
    if (lstatSync(installed).isSymbolicLink()) return false;
    const realInstalled = realpathSync(installed);
    const realCheckout = realpathSync(checkout);
    return (
      realInstalled === realCheckout ||
      realInstalled.startsWith(realCheckout + sep)
    );
  } catch {
    return false;
  }
}

function failedResult(execution, convention, invocations, command, failure) {
  return {
    ok: false,
    reused: false,
    convention,
    invocations,
    report: failureReport(execution, command, failure),
  };
}

function delegatedResult(execution, convention, invocations, reused) {
  invocations.push({
    role: "delegate",
    command: "implementation",
    cwd: execution,
    code: 0,
    stdout: "",
    stderr: "",
  });
  return { ok: true, reused, convention, invocations, report: null };
}

async function runOrdinaryReadiness(execution, env, convention, invocations) {
  const setup = await runCommand(execution, convention.setup, env);
  invocations.push({ role: "setup", ...setup });
  if (setup.code !== 0) {
    return failedResult(
      execution,
      convention,
      invocations,
      convention.setup,
      setup.stderr || `exit ${setup.code}`,
    );
  }

  const command = await runCommand(execution, convention.command, env);
  invocations.push({ role: "command", ...command });
  if (command.code !== 0) {
    return failedResult(
      execution,
      convention,
      invocations,
      convention.command,
      command.stderr || `exit ${command.code}`,
    );
  }

  return delegatedResult(execution, convention, invocations, false);
}

// Cheap substitute actor: follow the fixture's project-owned convention,
// reuse host-established preparation only for this checkout and dependency
// state when the command succeeds there, otherwise record setup then command,
// and delegate only after the command succeeds. Not product runtime.
export async function runReadinessGate(execution, env, options = {}) {
  const invocations = [];
  const convention = readProjectConvention(execution);
  if (convention.missing) {
    return failedResult(
      execution,
      convention,
      invocations,
      "missing",
      convention.reason,
    );
  }

  const currentState =
    typeof options.dependencyStateOf === "function"
      ? options.dependencyStateOf(execution)
      : undefined;
  const reusable =
    hostEvidenceMatches(execution, options.hostPreparation, currentState) &&
    checkoutOwnsMutableInstall(execution);

  if (reusable) {
    const command = await runCommand(execution, convention.command, env);
    if (command.code === 0) {
      invocations.push({ role: "command", ...command });
      return delegatedResult(execution, convention, invocations, true);
    }
  }

  return runOrdinaryReadiness(execution, env, convention, invocations);
}

// Git mechanics for one validated execution increment or owned repair.
// The caller supplies the owned workspace, the owned unpublished suffix,
// the authorized remote target, and how the accepted result is registered.
// This pushes only that target. Stash, checkout refresh, and observer startup
// stay with their own owners. Installed guidance is the agent's contract.
import {
  git,
  lsRemoteSha,
  originTrackingRef,
  pushExactRef,
  revParse,
} from "./publication-test-fixtures.mjs";

async function fetchedTarget(workspace, targetRef) {
  try {
    return await revParse(workspace, originTrackingRef(targetRef));
  } catch (error) {
    const text = `${error.stderr ?? ""}\n${error.message ?? ""}`;
    if (
      error.code === 128 ||
      /unknown revision|Needed a single revision|ambiguous argument/.test(text)
    ) {
      return null;
    }
    throw error;
  }
}

export async function publishExecutionIncrement({
  workspace,
  branch,
  previouslyPublishedBase,
  targetRef,
  register,
}) {
  await git(workspace, "fetch", "origin");
  const remoteTip = await fetchedTarget(workspace, targetRef);
  const preRebaseSha = await revParse(workspace, branch);
  let candidate = preRebaseSha;
  if (remoteTip && remoteTip !== previouslyPublishedBase) {
    await git(
      workspace,
      "rebase",
      "--onto",
      remoteTip,
      previouslyPublishedBase,
      branch,
    );
    candidate = await revParse(workspace, branch);
    if (candidate === preRebaseSha) {
      throw new Error("rebase left the pre-rebase SHA as the candidate");
    }
  }
  await pushExactRef(workspace, candidate, targetRef);
  await git(workspace, "fetch", "origin");
  const origin = (
    await git(workspace, "remote", "get-url", "origin")
  ).stdout.trim();
  const acceptedTip = await lsRemoteSha(origin, targetRef);
  if (acceptedTip !== candidate) {
    throw new Error("remote did not accept the candidate");
  }
  const receipt = { sha: candidate, target: targetRef };
  register?.(receipt);
  return { ok: true, receipt, preRebaseSha };
}

// Published queued source and local unpublished selected-source checks.
import { readFileSync } from "node:fs";
import { dirname, join, posix, relative, resolve, sep } from "node:path";
import {
  parseBacklog,
  queueHeading,
  takenHeading,
} from "../../dough-product-backlog/scripts/product-backlog-document.mjs";
import { readHome } from "../../dough-product-backlog/scripts/product-backlog-home-reader.mjs";
import { readStoryState } from "../../dough-product-backlog/scripts/product-backlog-story-state.mjs";
import { git } from "./publication-git.mjs";
import { backlogPath } from "./workspace-publication-ownership.mjs";

async function show(cwd, rev, path) {
  try {
    return (await git(cwd, "show", `${rev}:${path}`)).stdout;
  } catch {
    return null;
  }
}

function within(root, path) {
  const project = resolve(root);
  const absolute = resolve(project, path);
  if (absolute !== project && !absolute.startsWith(project + sep))
    throw new Error(`source path escapes project: ${path}`);
  return relative(project, absolute).split(sep).join("/");
}

function selectedRegion(source, href) {
  if (source === null) return null;
  const home = readHome(source, href);
  const lines = home.document.lines.slice(home.region.start, home.region.end);
  // A sibling section may add separator lines at this boundary. Preserve
  // whitespace within the selected section, including trailing spaces on text.
  while (lines.at(-1) === "") lines.pop();
  return lines.join("\n");
}

async function unpublishedSource(integration, remoteRef, path, href) {
  const base = (
    await git(integration, "merge-base", "HEAD", remoteRef)
  ).stdout.trim();
  const head = await show(integration, "HEAD", path);
  const index = await show(integration, "", path);
  let worktree;
  try {
    worktree = readFileSync(join(integration, path), "utf8");
  } catch {
    worktree = null;
  }
  const versions = [await show(integration, base, path), head, index, worktree];
  const selected = versions.map((source) =>
    href ? selectedRegion(source, href) : source,
  );
  return selected.some(
    (value, index) => index > 0 && value !== selected[index - 1],
  );
}

export async function readPublishedExecutionSource(request, remoteRef) {
  const backlog = await show(request.integration, remoteRef, backlogPath);
  if (backlog === null) throw new Error("fetched trunk has no product backlog");
  const entry = parseBacklog(backlog).entries.find(
    (item) => item.identity === request.identity,
  );
  if (
    !entry ||
    (entry.list !== queueHeading &&
      !(request.retained && entry.list === takenHeading))
  )
    throw new Error("selected identity is not queued on fetched trunk");
  const backlogDir = dirname(backlogPath);
  const homePath = within(
    request.integration,
    posix.join(backlogDir, entry.href.split("#")[0]),
  );
  const home = await show(request.integration, remoteRef, homePath);
  if (home === null)
    throw new Error("selected canonical home is absent on fetched trunk");
  const preview = readStoryState(home, entry.href);
  if (preview.identity !== request.identity || preview.status !== "recorded")
    throw new Error("selected canonical preparation or identity is unresolved");
  let planPath, plan, planTarget;
  if (preview.approach.kind === "planned") {
    planPath = within(
      request.integration,
      posix.join(dirname(homePath), preview.approach.plan),
    );
    plan = await show(request.integration, remoteRef, planPath);
    if (plan === null) throw new Error("published plan is absent");
    planTarget = posix.relative(backlogDir, planPath);
    if (entry.plan && entry.plan.target !== planTarget)
      throw new Error("queued plan link disagrees with preparation");
    if (request.plan && request.plan !== planTarget)
      throw new Error("requested plan disagrees with published preparation");
  } else if (
    preview.approach.kind !== "planless" ||
    request.plan ||
    entry.plan
  ) {
    throw new Error("queued planless authority or plan link is inconsistent");
  }
  const preparation = readStoryState(
    home,
    entry.href,
    planPath ? { planSource: plan } : {},
  );
  if (preparation.assessment.status !== "ready")
    throw new Error(
      `published preparation is ${preparation.assessment.status}`,
    );
  if (
    await unpublishedSource(
      request.integration,
      remoteRef,
      homePath,
      entry.href,
    )
  )
    throw new Error(
      "unpublished selected story source in originating checkout",
    );
  if (
    planPath &&
    (await unpublishedSource(request.integration, remoteRef, planPath, null))
  )
    throw new Error("unpublished selected plan in originating checkout");
  return {
    entry,
    homePath,
    planPath,
    planTarget,
    preparation,
    selectedSource: selectedRegion(home, entry.href),
    planSource: plan,
  };
}
